import hashlib
import sys


def oku(p):
    return open(p, encoding="utf-8").read()


def yaz(p, s):
    open(p, "w", encoding="utf-8").write(s)


def md5(s):
    return hashlib.md5(s.encode("utf-8")).hexdigest()


def dur(m):
    print("HATA: " + m)
    sys.exit(1)


