ESKI_SATIR = '    return WORD_RE.sub(lambda m: _tur_s(_nisbe_iye(_tur_l(_tur_k(_tur_j(_he_ki(kelime(m), m.group(0)), m.group(0)), m.group(0)), m.group(0)), m.group(0)), m.group(0)), sentence)'
YENI_SATIR = '    return WORD_RE.sub(lambda m: _tur_t(_tur_s(_nisbe_iye(_tur_l(_tur_k(_tur_j(_he_ki(kelime(m), m.group(0)), m.group(0)), m.group(0)), m.group(0)), m.group(0)), m.group(0)), m.group(0)), sentence)'
BLOK = '\n\n_TUR_T_HARIC = ("\xf6nd\xfcl", "\xf6ng\xfct")\n_TUR_T_SERT = set("\xe7fhkps\u015ft")\n_TUR_T_FIIL_ISIM = {"aktar", "devir", "k\u0131y", "sor", "dur", "kur", "yap"}   # T\xfcrk\xe7e fiil k\xf6k\xfc = Arap\xe7a/T\xfcrk\xe7e isim\n# Tur T: ek-fiil (hikaye -dI/-tI/-ydI, -dIm, \u015fart -sA/-ysA) s\xf6zl\xfckteki isim/s\u0131fat k\xf6k\xfcnden sonra\n_TUR_T_KOPULA = [(e, "y", "\\u06cc\\u062f\\u06cc") for e in ("yd\u0131", "ydi", "ydu", "yd\xfc")] + \\\n    [(e, "y", "\\u06cc\\u062f\\u0645") for e in ("yd\u0131m", "ydim", "ydum", "yd\xfcm")] + \\\n    [(e, "y", "\\u06cc\\u0633\\u0647") for e in ("ysa", "yse")] + \\\n    [(e, "d", "\\u062f\\u0645") for e in ("d\u0131m", "dim", "dum", "d\xfcm")] + \\\n    [(e, "t", "\\u062f\\u0645") for e in ("t\u0131m", "tim", "tum", "t\xfcm")] + \\\n    [(e, "d", "\\u062f\\u06cc") for e in ("d\u0131", "di", "du", "d\xfc")] + \\\n    [(e, "t", "\\u062f\\u06cc") for e in ("t\u0131", "ti", "tu", "t\xfc")] + \\\n    [(e, "s", "\\u0633\\u0647") for e in ("sa", "se")]\n\n\ndef _tur_t_fiil(kok: str) -> bool:\n    """Fiil k\xf6k\xfc m\xfc: k\xf6k s\xf6zl\xfc\u011f\xfc ya da yaln\u0131z fiile gelen eklerle (-iyor, -arak, -mak, -maz) s\xf6zl\xfckte/Hayrat\'ta ge\xe7iyor (san- san\u0131yor)."""\n    if _fiil_koku_mu(kok):\n        return True\n    for e in ("\u0131yor", "iyor", "uyor", "\xfcyor", "yor", "arak", "erek", "yarak", "yerek", "maz", "mez", "mak", "mek",\n              "\u0131r\u0131m", "irim", "urum", "\xfcr\xfcm", "\u0131p", "ip", "up", "\xfcp", "\u0131nca", "ince", "unca", "\xfcnce", "acak", "ecek",\n              "d\u0131\u011f\u0131", "di\u011fi", "du\u011fu", "d\xfc\u011f\xfc", "t\u0131\u011f\u0131", "ti\u011fi", "tu\u011fu", "t\xfc\u011f\xfc", "mad\u0131", "medi"):\n        w = kok + e\n        if w in dictionary.HAYRAT_ANAHTAR or w in dictionary.HAYRAT_TEK or dictionary.lookup_exact(w):\n            return True\n    return False\n\n\ndef _tur_t_kopula(wl: str):\n    """cahildi \u062c\u0627\u0647\u0644\u062f\u06cc\u060c m\xfcthi\u015fti \u0645\u062f\u0647\u0634\u062f\u06cc\u060c sahipse \u0635\u0627\u062d\u0628\u0633\u0647\u060c sarho\u015ftum \u0633\u0631\u062e\u0648\u0634\u062f\u0645\u060c hakikiydi \u062d\u0642\u06cc\u0642\u06cc\u062f\u06cc. K\xf6k s\xf6zl\xfckte tam kay\u0131tl\u0131, fiil de\u011fil."""\n    for ek, tur, yazi in _TUR_T_KOPULA:\n        if not wl.endswith(ek):\n            continue\n        kok = wl[: -len(ek)]\n        if len(kok) < 3:\n            return None\n        son = kok[-1]\n        unlu = son in "ae\u0131io\xf6u\xfc\xe2\xee\xfb"\n        if tur == "y" and not unlu:\n            return None\n        if tur in "ds" and unlu:\n            return None\n        if tur == "d" and son in _TUR_T_SERT:\n            return None\n        if tur == "t" and son not in _TUR_T_SERT:\n            return None\n        if _tur_t_fiil(kok) or (re.search(r"[\u0131iu\xfc][ln]$", kok) and _tur_t_fiil(kok[:-2])) \\\n                or re.search(r"m[ae]$", kok) or _tur_t_fiil(kok[:-1]):\n            return None\n        if re.search(r"(yor|[ae]c[ae]k|m[\u0131iu\xfc]\u015f|m[ae]z|[dt][\u0131iu\xfc]r|[dt][\u0131iu\xfc]k|[dt][\u0131iu\xfc]|[ae\u0131iu\xfc]rl[ae]r)(l[ae]r)?$", kok):\n            return None                          # \xe7ekimli fiil (yemiyorlar+d\u0131\u060c vermeyecek+tim\u060c dayan\u0131lmaz+d\u0131\u060c verdi+yse)\n        if tur == "s" and len(kok) < 4:\n            return None                          # Bursa\u060c kasa\n        if tur in "dt" and (dictionary.lookup_exact(wl[:len(kok) + 1]) or wl[:len(kok) + 1] in dictionary.HAYRAT_ANAHTAR):\n            return None                          # baht+\u0131\u060c baht\u0131m\u060c s\u0131rt+\u0131\u060c redd+i (belirtme/iyelik)\n        if kok in _TUR_T_FIIL_ISIM or re.search(r"[\u0131iu\xfc]?l[ae]n$", kok) or \\\n                (re.search(r"[ae\u0131iu\xfc]r$", kok) and _tur_t_fiil(kok[:-2])):\n            return None                          # aktar-\u060c devir-\u060c yenilen-\u060c as+ar+sa (fiil)\n        hit = dictionary.lookup_exact(kok)\n        if not hit or " " in hit[0]:\n            return None\n        k = transliterate_text(kok)              # k\xf6k tek ba\u015f\u0131na nas\u0131l yaz\u0131l\u0131yorsa (olmas\u0131 \u0627\u0648\u0644\u0645\u0627\u0633\u06cc\u060c iyi \u0627\u06cc\u06cc)\n        if " " in k or not k:\n            return None\n        if tur == "y" and k.endswith("\\u06cc"):\n            yazi = yazi[1:]                       # hakikiydi \u062d\u0642\u06cc\u0642\u06cc\u062f\u06cc (Hayrat hus\xfbs\xeeydi \u062e\u0635\u0648\u0635\u06cc\u062f\u06cc)\n        elif tur == "y" and k.endswith("\\u0647"):\n            k += "\\u200c"                        # fazlayd\u0131 \u0641\u0636\u0644\u0647\u200c\u06cc\u062f\u06cc\n        return k + yazi\n    return None\n\n\ndef _tur_t(o: str, latin: str) -> str:\n    """Tur T (26 Ekim): (1) \xf6n ve y\xf6n aileleri k\xe2f-\u0131 n\xfbn\xee ile (Zahir: y\xf6n de genizden; Hayrat \xf6n \u0627\u0648\u06ad\u060c \xf6nce \u0627\u0648\u06ad\u062c\u0647\u060c y\xf6nelt \u06cc\u0648\u06ad\u0644\u062a); Hayrat\'taki\n    ve s\xf6zl\xfckteki kelimede de uygulan\u0131r (Hayrat y\xf6n\xfcnden \u06cc\u0648\u0646\u0646\u062f\u0646\u060c \xf6nemi \u0623\u0648\u0646\u0645\u06cc hata say\u0131l\u0131r). on, onu/onda/ondan, yont-, yonca etkilenmez.\n    (2) Hayrat\'ta ve s\xf6zl\xfckte tam kayd\u0131 olmayan kelimede: ek-fiil (cahildi\u060c sahipse)\u060c -dAydI (yan\u0131ndayd\u0131 \u06cc\u0627\u0646\u0646\u062f\u0647\u200c\u06cc\u062f\u06cc)\u060c -mIyor \u0645\u06cc\u06cc\u0648\u0631\n    (Hayrat 729 / \u0645\u0627\u06cc\u0648\u0631 256)\u060c -mAktAydI \u0645\u0642\u062f\u0647\u200c\u06cc\u062f\u06cc. OSM_TUR_T=0 kapat\u0131r."""\n    if _os.environ.get("OSM_TUR_T", "1") == "0" or not o:\n        return o\n    wl = turkish_lower(latin).replace("\\u2019", "\'")\n    if not (wl in dictionary.HAYRAT_ANAHTAR or wl in dictionary.HAYRAT_TEK or dictionary.lookup_exact(wl)) and "\'" not in wl:\n        k = _tur_t_kopula(wl) if " " not in o else None   # bile\u015fik fiil (\u015fevketti \u0634\u0648\u0642 \u0627\u06cc\u062a\u062f\u06cc) de\u011fil\n        if k:\n            o = k\n        m = re.match(r"^(.{3,}[dt][ae])yd([\u0131i])(m|n|k|lar|ler)?$", wl)\n        if m and " " not in o:\n            _k = transliterate_text(latin[:len(m.group(1))])\n            if _k.endswith("\\u062f\\u0647") and " " not in _k:   # yan\u0131ndayd\u0131 \u06cc\u0627\u0646\u0646\u062f\u0647\u200c\u06cc\u062f\u06cc\u060c haldeydi \u062d\u0627\u0644\u062f\u0647\u200c\u06cc\u062f\u06cc\u060c zorundayd\u0131\n                _son = {None: "\\u06cc", "m": "\\u0645", "n": "\\u06ad", "k": "\\u0643" if m.group(2) == "i" else "\\u0642",\n                        "lar": "\\u06cc\\u0644\\u0631", "ler": "\\u06cc\\u0644\\u0631"}[m.group(3)]\n                o = _k + "\\u200c\\u06cc\\u062f" + _son\n        m = re.search(r"^(.*?)m[\u0131u]yor", wl)\n        if m and "\\u0645\\u0627\\u06cc\\u0648\\u0631" in o and (re.search(r"[ae]$", m.group(1)) or _fiil_koku_mu(m.group(1))):\n            o = o.replace("\\u0645\\u0627\\u06cc\\u0648\\u0631", "\\u0645\\u06cc\\u06cc\\u0648\\u0631", 1)   # korkmuyor \u0642\u0648\u0631\u0642\u0645\u06cc\u06cc\u0648\u0631\n        if re.search(r"(mak|mek)t[ae]yd[\u0131i]", wl):\n            o = re.sub("(\\u0645[\\u0627]?[\\u0642\\u0643])\\u062a[\\u0627\\u06cc]+\\u062f", "\\\\1\\u062f\\u0647\\u200c\\u06cc\\u062f", o, 1)\n            o = o.replace("\\u0645\\u0627\\u0642\\u062f\\u0647", "\\u0645\\u0642\\u062f\\u0647", 1)   # bulunmaktayd\u0131 \u0628\u0648\u0644\u0648\u0646\u0645\u0642\u062f\u0647\u200c\u06cc\u062f\u06cc\n        if not k and re.search(r"[\u0131i]yd[\u0131i]$", wl) and o.endswith("\\u06cc\\u06cc\\u062f\\u06cc"):\n            _k = transliterate_text(latin[:-3]) if len(wl) >= 7 else ""\n            if _k.endswith("\\u06cc") and " " not in _k:\n                o = _k + "\\u062f\\u06cc"           # biriydi \u0628\u0631\u06cc\u062f\u06cc\u060c kendisiydi \u0643\u0646\u062f\u06cc\u0633\u06cc\u062f\u06cc\n    if wl.startswith("\xf6n") and not wl.startswith(_TUR_T_HARIC):\n        o = re.sub("^[\\u0627\\u0623]\\u0648\\u0646", "\\u0627\\u0648\\u06ad", o)\n    elif wl.startswith("y\xf6n"):\n        o = re.sub("^\\u06cc\\u0648\\u0646", "\\u06cc\\u0648\\u06ad", o)\n        if wl.startswith("y\xf6nel"):\n            o = re.sub("^\\u06cc\\u0648\\u06ad\\u0647\\u200c?\\u0644", "\\u06cc\\u0648\\u06ad\\u0644", o)\n    return o'
